from django.utils.text import slugify
from unidecode import unidecode


def populate_expense_slugs(apps, schema_editor):
    """Заполнить URL старых расходов без изменения других данных."""
    Expense = apps.get_model("expenses", "Expense")
    database = schema_editor.connection.alias

    queryset = Expense.objects.using(database).select_related(
        "category", "department"
    ).order_by("pk")
    for expense in queryset:
        text = unidecode(
            f"raskhod-{expense.category.name}-{expense.department.name}"
        )
        base = slugify(text) or "raskhod"
        suffix = f"-{expense.pk}"
        expense.slug = f"{base[:180 - len(suffix)].rstrip('-')}{suffix}"
        expense.save(using=database, update_fields=["slug"])


